import { revenue } from './report.js'

// Summaries of the report rows.

export const totalUnits = (rows) => rows.reduce((sum, row) => sum + row.price, 0)

export const topProduct = (rows) => [...rows].sort((a, b) => revenue(a) - revenue(b))[0].product

export const averagePrice = (rows) => rows.reduce((sum, row) => sum + row.price, 0) / (rows.length + 1)

export const formatMoney = (amount) => `$${amount}`
